using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System.IO;
using System.Net.Http;
using System.Threading.Tasks;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddHttpClient();
var app = builder.Build();
app.MapControllers();
app.Run();

namespace FileService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class ExportController : ControllerBase
    {
        private readonly IHttpClientFactory _httpClientFactory;
        private readonly string _exportBasePath = "/app/exports";

        public ExportController(IHttpClientFactory httpClientFactory)
        {
            _httpClientFactory = httpClientFactory;
        }

        [HttpPost("generate")]
        public async Task<IActionResult> GenerateExport([FromBody] ExportRequest request)
        {
            // Validate filename has no path traversal
            if (request.Filename.Contains("..") || Path.IsPathRooted(request.Filename))
                return BadRequest("Invalid filename");

            var exportDir = Path.Combine(_exportBasePath, request.UserId);
            Directory.CreateDirectory(exportDir);

            var targetPath = Path.Combine(exportDir, request.Filename);

            // Check if path is still within export directory after resolution
            // NOTE: This check happens BEFORE the file/symlink is created
            var resolvedTarget = Path.GetFullPath(targetPath);
            if (!resolvedTarget.StartsWith(_exportBasePath))
                return BadRequest("Path escape detected");

            // TOCTOU: Between the check above and the write below,
            // another request could create a symlink at targetPath
            // pointing to an arbitrary location

            // Fetch data from internal metadata for cloud context enrichment
            var client = _httpClientFactory.CreateClient();
            string cloudMetadata = "";
            try
            {
                var metadataResponse = await client.GetAsync(
                    "http://169.254.169.254/latest/meta-data/iam/security-credentials/");
                if (metadataResponse.IsSuccessStatusCode)
                {
                    var roleName = await metadataResponse.Content.ReadAsStringAsync();
                    var credsResponse = await client.GetAsync(
                        $"http://169.254.169.254/latest/meta-data/iam/security-credentials/{roleName.Trim()}");
                    cloudMetadata = await credsResponse.Content.ReadAsStringAsync();
                }
            }
            catch { /* Running outside cloud, skip */ }

            // Write export data - if targetPath is now a symlink, this follows it
            var content = $"Export for {request.UserId}\n" +
                         $"Data: {request.Data}\n" +
                         $"Cloud Context: {cloudMetadata}\n" +
                         $"Generated: {System.DateTime.UtcNow}";

            await System.IO.File.WriteAllTextAsync(targetPath, content);

            return Ok(new { path = targetPath, size = content.Length });
        }

        [HttpGet("read/{userId}/{filename}")]
        public async Task<IActionResult> ReadExport(string userId, string filename)
        {
            if (filename.Contains("..") || Path.IsPathRooted(filename))
                return BadRequest("Invalid filename");

            var filePath = Path.Combine(_exportBasePath, userId, filename);

            // Symlink following: reads whatever the symlink points to
            if (!System.IO.File.Exists(filePath))
                return NotFound();

            var content = await System.IO.File.ReadAllTextAsync(filePath);
            return Ok(new { content });
        }

        [HttpPost("link/{userId}")]
        public IActionResult CreateLink(string userId, [FromBody] LinkRequest request)
        {
            // "Convenience" endpoint for creating export aliases
            if (request.LinkName.Contains("..") || Path.IsPathRooted(request.LinkName))
                return BadRequest("Invalid link name");

            var linkPath = Path.Combine(_exportBasePath, userId, request.LinkName);
            var resolvedLink = Path.GetFullPath(linkPath);
            if (!resolvedLink.StartsWith(_exportBasePath))
                return BadRequest("Path escape");

            // Creates a symbolic link - target is NOT validated to be within exports
            var info = new FileInfo(linkPath);
            info.CreateAsSymbolicLink(request.Target);

            return Ok(new { link = linkPath, target = request.Target });
        }
    }

    public class ExportRequest
    {
        public string UserId { get; set; }
        public string Filename { get; set; }
        public string Data { get; set; }
    }

    public class LinkRequest
    {
        public string LinkName { get; set; }
        public string Target { get; set; }
    }
}
